/* Movable people/cutout layers; their local masks and image blobs remain editable. */
(() => {
 'use strict';
 const api=RayCompose,core=RayComposeCore,wrap=document.getElementById('canvasWrap'),stage=document.getElementById('stage'),app=document.querySelector('.film-workspace');
 const group=document.createElement('section');group.className='grp compose-group';group.id='grpPeople';group.dataset.toolOnly='people';group.hidden=true;group.innerHTML='<p class="lbl">Ghép người, vật & sticker</p><label class="bbtn compose-file">＋ Thêm người / vật<input type="file" accept="image/*" id="personFile" aria-label="Thêm ảnh người hoặc vật để ghép"></label><p class="hint" id="personStatus" role="status">PNG hoặc sticker trong suốt ghép được ngay. Ảnh thường có thể tách vật bằng Tạo sticker, tách người bằng AI hoặc sửa bằng bút. Tối đa 4 lớp.</p><div class="compose-text-list" id="personList" role="group" aria-label="Các lớp đã ghép"></div><p class="compose-title">Thứ tự lớp ghép</p><div class="compose-actions person-order-tools"><button type="button" class="bbtn" id="raisePerson">↑ Đưa ra trước</button><button type="button" class="bbtn" id="lowerPerson">↓ Đưa ra sau</button></div><p class="compose-title">So với chủ thể gốc</p><div class="seg person-depth-tools" id="personDepth" role="group" aria-label="Vị trí so với chủ thể gốc"><button type="button" data-depth="front">Phía trước</button><button type="button" data-depth="back">Phía sau</button></div><p class="hint" id="personDepthStatus" role="status">Chọn lớp để sắp xếp.</p><label class="row"><span class="t">Kích thước lớp<em id="personSizeValue"></em></span><input type="range" id="personSize" aria-label="Kích thước lớp ghép" min="0.05" max="3" step="0.01"></label><div class="compose-actions person-scale-tools"><button type="button" class="bbtn" id="shrinkPerson">− Thu nhỏ</button><button type="button" class="bbtn" id="growPerson">Phóng to ＋</button></div><p class="hint">Kéo giữa lớp ghép để di chuyển. Kéo nút ↗ ở góc để phóng to hoặc thu nhỏ, giữ nguyên tỉ lệ.</p><div class="compose-actions"><button type="button" class="bbtn" id="cutPersonAI">✦ Tách người bằng AI</button><button type="button" class="bbtn" id="stopPersonAI" hidden>Dừng AI</button><button type="button" class="bbtn" id="togglePerson">Ẩn lớp này</button><button type="button" class="bbtn" id="deletePerson">Xóa lớp này</button></div><div class="seg" id="personEditModes" role="group" aria-label="Chỉnh lớp ghép"><button type="button" data-mode="move">Kéo vị trí</button><button type="button" data-mode="erase">Xóa nền lớp</button><button type="button" data-mode="restore">Khôi phục</button></div><label class="row"><span class="t">Góc xoay lớp<em id="personAngleValue"></em></span><input type="range" id="personAngle" aria-label="Góc xoay lớp" min="-180" max="180" step="1"></label><label class="row"><span class="t">Độ hiện lớp<em id="personOpacityValue"></em></span><input type="range" id="personOpacity" aria-label="Độ hiện lớp ghép" min="0.05" max="1" step="0.01"></label><div class="compose-actions"><button type="button" class="bbtn" id="flipPerson">↔ Lật lớp</button><button type="button" class="bbtn" id="centerPerson">Về giữa ảnh</button></div><div id="personBrushControls" hidden><label class="row"><span class="t">Cỡ bút<em id="personBrushSizeValue"></em></span><input type="range" id="personBrushSize" aria-label="Cỡ bút xóa nền lớp ghép" min="0.02" max="0.45" step="0.005" value="0.12"></label><label class="row"><span class="t">Mềm viền bút<em id="personBrushSoftValue"></em></span><input type="range" id="personBrushSoft" aria-label="Mềm viền bút lớp ghép" min="0" max="1" step="0.01" value="0.65"></label><button type="button" class="bbtn" id="undoPersonStroke">Bỏ nét bút cuối</button></div><p class="hint">Kéo trực tiếp trên ảnh để đặt lớp ghép. Màu phim áp dụng chung cho ảnh và các lớp ghép. Ẩn/Xóa chỉ tác động lớp đang chọn; Quay lại để hoàn tác.</p>';
 document.querySelector('.panel>.scroll').append(group);const $=id=>document.getElementById(id),uid=()=>crypto.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2);
 let mode='move',dragging=false,brushSize=.12,brushSoft=.65,reading=false;
 const current=()=>{const s=api.capture();return s.people.find(p=>p.id===s.selectedPerson)||s.people.at(-1)||null;};
 function update(values,record=false){const p=current();if(!p)return;const fn=s=>({...s,people:s.people.map(x=>x.id===p.id?{...x,...values}:x)});record?api.edit('Chỉnh lớp ghép',fn):api.update(fn);sync();}
 $('personFile').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!source||!file||reading||api.busy||api.capture().people.length>=4)return;reading=true;$('personStatus').textContent='Đang mở ảnh để ghép…';sync();const raw=source;try{const asset={id:uid(),blob:file,name:file.name,role:'person'};await api.asset(asset);if(raw!==source)return;const person={id:uid(),asset,x:.5,y:.52,size:.55,angle:0,flipX:false,flipY:false,opacity:1,hidden:false,behindSubject:false,mask:null,softness:.18,strokes:[]};api.edit('Thêm ảnh để ghép',s=>({...s,people:[...s.people,person],selectedPerson:person.id}));mode='move';$('personStatus').textContent='Đã thêm ảnh. Chọn Tạo sticker để tách vật, Tách người bằng AI cho ảnh người, hoặc dùng bút Xóa nền lớp.';}catch(error){$('personStatus').textContent=error.message||'Chưa đọc được ảnh.';}finally{reading=false;sync();}};
 $('cutPersonAI').onclick=async()=>{const p=current();if(!p)return;const work=api.segmentPerson(p.id);sync();await work;sync();};$('stopPersonAI').onclick=()=>{api.cancel();$('personStatus').textContent='Đã dừng AI. Vẫn có thể xóa nền bằng bút.';sync();};
 $('deletePerson').onclick=()=>{const p=current();if(p)api.edit('Xóa lớp ghép',s=>{const people=s.people.filter(x=>x.id!==p.id);return{...s,people,selectedPerson:people.at(-1)?.id||null};});sync();};
 $('togglePerson').onclick=()=>{const p=current();if(p)update({hidden:!p.hidden},true);};$('flipPerson').onclick=()=>{const p=current();if(p)update({flipX:!p.flipX},true);};$('centerPerson').onclick=()=>update({x:.5,y:.5},true);
 for(const [id,amount]of [['shrinkPerson',-.05],['growPerson',.05]])$(id).onclick=()=>{const p=current();if(p)update({size:clamp(p.size+amount,.05,3)},true);};
 for(const [id,key]of [['personSize','size'],['personAngle','angle'],['personOpacity','opacity']])$(id).oninput=e=>update({[key]:Number(e.target.value)});
 for(const [id,direction]of [['raisePerson','front'],['lowerPerson','back']])$(id).onclick=()=>{const p=current();if(!p)return;api.edit(direction==='front'?'Đưa lớp ra trước':'Đưa lớp ra sau',s=>({...s,people:core.movePerson(s.people,p.id,direction)}));sync();};
 $('personDepth').onclick=async e=>{const depth=e.target.closest('button')?.dataset.depth,p=current();if(!depth||!p)return;const work=api.setPersonDepth(p.id,depth==='back');sync();await work;sync();};
 $('personEditModes').onclick=e=>{const value=e.target.closest('button')?.dataset.mode;if(value){mode=value;sync();}};$('personBrushSize').oninput=e=>{brushSize=Number(e.target.value);sync();};$('personBrushSoft').oninput=e=>{brushSoft=Number(e.target.value);sync();};$('undoPersonStroke').onclick=()=>{const p=current();if(p)update({strokes:p.strokes.slice(0,-1)},true);};
 const overlay=document.createElement('div');overlay.id='personOverlay';overlay.className='person-overlay';overlay.hidden=true;const brush=document.createElement('div');brush.id='personBrushSurface';brush.className='person-brush-surface';brush.hidden=true;const cursor=document.createElement('div');cursor.className='brush-cursor';cursor.hidden=true;brush.append(cursor);wrap.append(overlay,brush);
 function geometry(){return bodyGeo();}
 function normalized(p,image,g,x,y){const r=core.personSize(p,image,g.W,g.H),dx=(x-g.ox)/g.k-p.x*g.W,dy=(y-g.oy)/g.k-p.y*g.H,a=(p.angle||0)*Math.PI/180;return[(dx*Math.cos(a)+dy*Math.sin(a))*(p.flipX?-1:1)/r.width+.5,(-dx*Math.sin(a)+dy*Math.cos(a))*(p.flipY?-1:1)/r.height+.5];}
 function showCursor(g,p,image,x,y){const r=core.personSize(p,image,g.W,g.H);cursor.hidden=false;Object.assign(cursor.style,{left:x-g.ox+'px',top:y-g.oy+'px',width:Math.min(r.width,r.height)*g.k*brushSize+'px',height:Math.min(r.width,r.height)*g.k*brushSize+'px'});}
 RayControls.bindDrag(brush,{start(e){const p=current(),g=geometry(),image=api.image(p?.asset);if(!p||!g||!image||api.busy)return;const pt=normalized(p,image,g,e.clientX,e.clientY);if(pt.some(v=>v<0||v>1))return;RaySession.record();const s={p,g,image,points:[pt],before:p.strokes,mode:mode==='erase'?'erase':'paint'};showCursor(g,p,image,e.clientX,e.clientY);update({strokes:[...s.before,{mode:s.mode,size:brushSize,softness:brushSoft,points:s.points.slice()}]});return s;},move(s,e){s.points.push(normalized(s.p,s.image,s.g,e.clientX,e.clientY));showCursor(s.g,s.p,s.image,e.clientX,e.clientY);update({strokes:[...s.before,{mode:s.mode,size:brushSize,softness:brushSoft,points:s.points.slice()}]});},end(){cursor.hidden=true;RaySession.record('Sửa nền lớp ghép');}});
 function syncOverlay(){const visible=!!source&&document.body.dataset.editorTool==='people'&&!app.classList.contains('is-result-preview')&&!api.busy&&!reading&&!window.RayRemove?.busy;overlay.hidden=!visible;stage.classList.toggle('people-editing',visible);const p=current(),g=geometry(),wr=wrap.getBoundingClientRect();brush.hidden=!visible||mode==='move'||!p||p.hidden;if(g)Object.assign(brush.style,{left:g.ox-wr.left+'px',top:g.oy-wr.top+'px',width:g.W*g.k+'px',height:g.H*g.k+'px'});if(dragging)return;overlay.replaceChildren();if(!visible||!g)return;
  for(const person of core.orderPeople(api.capture().people)){const image=api.image(person.asset);if(person.hidden||!image)continue;const r=core.personSize(person,image,g.W,g.H),hit=document.createElement('button');hit.type='button';hit.className='person-layer-hit'+(person.id===p?.id?' selected':'');hit.dataset.personId=person.id;hit.setAttribute('aria-label','Kéo lớp ghép '+person.asset.name);hit.style.pointerEvents=mode==='move'?'auto':'none';Object.assign(hit.style,{left:g.ox-wr.left+person.x*g.W*g.k+'px',top:g.oy-wr.top+person.y*g.H*g.k+'px',width:r.width*g.k+'px',height:r.height*g.k+'px',transform:'translate(-50%,-50%) rotate('+person.angle+'deg)'});RayControls.bindDrag(hit,{start(){api.edit('Chọn lớp ghép',s=>({...s,selectedPerson:person.id}));dragging=true;return{x:person.x,y:person.y,g};},move(s,e){const x=clamp(s.x+e.dx/(g.W*g.k),-.5,1.5),y=clamp(s.y+e.dy/(g.H*g.k),-.5,1.5);api.update(v=>({...v,people:v.people.map(o=>o.id===person.id?{...o,x,y}:o)}));hit.style.left=g.ox-wr.left+x*g.W*g.k+'px';hit.style.top=g.oy-wr.top+y*g.H*g.k+'px';},end(){dragging=false;sync();RaySession.record('Kéo lớp ghép');}});hit.onkeydown=e=>{const d={ArrowLeft:[-.005,0],ArrowRight:[.005,0],ArrowUp:[0,-.005],ArrowDown:[0,.005]}[e.key];if(!d)return;e.preventDefault();api.edit('Di chuyển lớp ghép',s=>({...s,selectedPerson:person.id,people:s.people.map(o=>o.id===person.id?{...o,x:o.x+d[0],y:o.y+d[1]}:o)}));sync();};overlay.append(hit);
   if(person.id===p?.id&&mode==='move'){
    const knob=document.createElement('button');knob.type='button';knob.className='person-resize-handle';knob.innerHTML='<span aria-hidden="true">↗</span>';knob.setAttribute('aria-label','Phóng to hoặc thu nhỏ lớp ghép');knob.title='Kéo góc để đổi cỡ; phím + / − để chỉnh từng nấc';
    const place=size=>{const box=core.personSize({...person,size},image,g.W,g.H),a=person.angle*Math.PI/180;hit.style.width=box.width*g.k+'px';hit.style.height=box.height*g.k+'px';knob.style.left=g.ox-wr.left+(person.x*g.W+(box.width*Math.cos(a)-box.height*Math.sin(a))/2)*g.k+'px';knob.style.top=g.oy-wr.top+(person.y*g.H+(box.width*Math.sin(a)+box.height*Math.cos(a))/2)*g.k+'px';};place(person.size);
    RayControls.bindDrag(knob,{start(){RaySession.record();dragging=true;return{person,g};},move(s,e){const size=core.resizePerson(s.person,image,g.W,g.H,e.dx/g.k,e.dy/g.k);update({size});place(size);},end(){dragging=false;sync();RaySession.record('Đổi cỡ lớp ghép');}});
    knob.onkeydown=e=>{const amount=['+','=','ArrowUp','ArrowRight'].includes(e.key)?.02:['-','ArrowDown','ArrowLeft'].includes(e.key)?-.02:0;if(!amount)return;e.preventDefault();const p=current();if(p)update({size:clamp(p.size+amount,.05,3)},true);};overlay.append(knob);
   }
  }
 }
 function sync(){const p=current(),disabled=!source||api.busy||reading||BEAUTY.busy||BODY_AI.busy||window.RayRemove?.busy;for(const b of group.querySelectorAll('button,input'))b.disabled=disabled||(!p&&!b.classList.contains('cutout-launcher'));const choose=$('personFile');choose.disabled=disabled||api.capture().people.length>=4;$('stopPersonAI').hidden=!api.busy;$('stopPersonAI').disabled=!api.busy;$('personBrushControls').hidden=mode==='move';$('personList').replaceChildren();for(const item of api.capture().people){const b=document.createElement('button');b.type='button';b.textContent=item.asset.name+(item.behindSubject?' · Sau chủ thể gốc':'')+(item.hidden?' · Ẩn':'');b.className=p?.id===item.id?'on':'';b.setAttribute('aria-pressed',String(p?.id===item.id));b.disabled=disabled;b.onclick=()=>{api.edit('Chọn lớp ghép',s=>({...s,selectedPerson:item.id}));sync();};$('personList').append(b);}for(const b of $('personEditModes').querySelectorAll('button')){b.classList.toggle('on',b.dataset.mode===mode);b.setAttribute('aria-pressed',String(b.dataset.mode===mode));}for(const b of $('personDepth').querySelectorAll('button')){const on=!!p&&(b.dataset.depth==='back')===!!p.behindSubject;b.classList.toggle('on',on);b.setAttribute('aria-pressed',String(on));}
  const peers=p?api.capture().people.filter(x=>!!x.behindSubject===!!p.behindSubject):[],index=peers.findIndex(x=>x.id===p?.id);$('raisePerson').disabled=disabled||index<0||index===peers.length-1;$('lowerPerson').disabled=disabled||index<=0;$('personDepthStatus').textContent=p?(p.behindSubject?'Sau chủ thể trong ảnh gốc':'Trước chủ thể trong ảnh gốc')+' · Lớp '+(index+1)+'/'+peers.length+'. Ra trước / Ra sau đổi thứ tự giữa các lớp ghép.':'Chọn lớp để sắp xếp.';
  if(p){$('togglePerson').textContent=p.hidden?'Hiện lớp này':'Ẩn lớp này';for(const [id,key,suffix]of [['personSize','size','%'],['personAngle','angle','°'],['personOpacity','opacity','%']]){$(id).value=p[key];$(id+'Value').textContent=(suffix==='%'?Math.round(p[key]*100):Math.round(p[key]))+suffix;}$('undoPersonStroke').disabled=disabled||!p.strokes.length;}$('personBrushSizeValue').textContent=Math.round(brushSize*100)+'%';$('personBrushSoftValue').textContent=Math.round(brushSoft*100)+'%';syncOverlay();}
 const oldDraw=draw;draw=function(){oldDraw();sync();};const oldSync=syncControls;syncControls=function(){oldSync();sync();};const toolChange=RayControls.onToolChange;RayControls.onToolChange=function(tool){toolChange(tool);sync();};new ResizeObserver(syncOverlay).observe(wrap);window.RayPeopleEditor={syncGeometry:syncOverlay};sync();
})();
